import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { canonicalSha256 } from '../src/core/canonical-json.mjs';
import { compileCapabilityGraphV2 } from '../src/capabilities/v2/compiler.mjs';
const ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const [legacy,skills,providers]=await Promise.all(['capabilities/catalog.json','skills-v2/catalog.json','providers/built-in-providers.json'].map((file)=>readFile(path.join(ROOT,file),'utf8').then(JSON.parse)));
const outcomes=legacy.map((item)=>{const contract={legacyCapabilityId:item.capabilityId,domain:item.domain,title:item.title,consumes:item.consumes,produces:item.produces,evidence:item.evidence,requiredTools:item.requiredTools,riskClass:item.riskClass};return{outcomeId:`outcome.${item.capabilityId}`,kind:'outcome',...contract,legacyScaffold:true,contractSha256:canonicalSha256(contract)};});
const providerBySkill=new Map(providers.filter((p)=>p.kind==='skill').map((p)=>[p.providerId.replace(/^local-skill\./,''),p]));
const techniqueManifests=new Map(await Promise.all(skills.map(async(entry)=>[entry.id,JSON.parse(await readFile(path.join(ROOT,entry.path,'manifest.json'),'utf8'))])));
const techniques=skills.map((entry)=>{const provider=providerBySkill.get(entry.id);const manifest=techniqueManifests.get(entry.id);const data={skillId:entry.id,skillContractVersion:2,maturity:entry.maturity,triggers:[manifest.identity.description,...manifest.identity.keywords],antiTriggers:[...manifest.identity.antiTriggers],domains:[...manifest.identity.domains],consumes:manifest.contract.consumes.map((item)=>item.type),produces:manifest.contract.produces.map((item)=>item.type),requiredTools:[...manifest.contract.requiredTools],optionalTools:[...manifest.contract.optionalTools],sectionIndexSha256:entry.sectionIndex.indexSha256,defaultSections:[...manifest.context.defaultSections],hardTokens:manifest.context.hardTokens,policyProfileHashes:manifest.policyProfileHashes,kernelLevel:manifest.kernelLevel??null,executionMode:manifest.executionProgram?.executionMode??'agent'};return{techniqueId:`technique.${entry.id}`,kind:'technique',...data,contractSha256:entry.manifestSha256};});
const providerNodes=skills.map((entry)=>{const p=providerBySkill.get(entry.id);return{providerId:p.providerId,kind:'provider',providerKind:'skill',status:p.status,providerDigest:p.providerDigest,sourceId:p.sourceId};});
const evaluators=skills.map((entry)=>{const manifest=techniqueManifests.get(entry.id);const payload={skillId:entry.id,benchmarkIds:[...(manifest.quality?.benchmarkIds??[])],evaluatorIds:[...(manifest.verification?.evaluatorIds??[])],trustedStoreRequired:true};return{evaluatorId:`evaluator.${entry.id}`,kind:'evaluator',...payload,contractSha256:canonicalSha256(payload)};});
const outcomeIds=new Set(outcomes.map((o)=>o.outcomeId));const relations=[];
for(const entry of skills){const manifest=techniqueManifests.get(entry.id);const mappings=(manifest.capabilityMappings??[]).filter((item)=>!item.capabilityId.startsWith('technique.'));if(mappings.length===0)throw new Error(`Technique ${entry.id} has no reviewed outcome mapping`);for(const mapping of mappings){const target=`outcome.${mapping.capabilityId}`;if(!outcomeIds.has(target))throw new Error(`Unknown mapped outcome ${target}`);relations.push({type:'satisfies',from:`technique.${entry.id}`,to:target,fitScore:mapping.fitScore,mappingEvidence:mapping.mappingEvidence,reviewer:mapping.reviewer,reviewedAt:mapping.reviewedAt});}const provider=providerBySkill.get(entry.id);if(!provider)throw new Error(`Missing built-in provider for technique ${entry.id}`);relations.push({type:'deliveredBy',from:`technique.${entry.id}`,to:provider.providerId});relations.push({type:'validatedBy',from:`technique.${entry.id}`,to:`evaluator.${entry.id}`});}
const graph=compileCapabilityGraphV2({schemaVersion:2,outcomes,techniques,providers:providerNodes,evaluators,relations});await mkdir(path.join(ROOT,'capabilities-v2'),{recursive:true});await writeFile(path.join(ROOT,'capabilities-v2/graph.json'),JSON.stringify(graph,null,2)+'\n');
for(const [name,records] of Object.entries({outcomes,techniques,providers:providerNodes,evaluators,relations}))await writeFile(path.join(ROOT,`capabilities-v2/${name}.json`),JSON.stringify(records,null,2)+'\n');
console.log(`Compiled Capability Graph v2: ${outcomes.length} outcomes, ${techniques.length} techniques, ${relations.length} relations.`);
